API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Ingress_and_TLS_Termination_Controller, "Ingress and TLS Termination Controller", "AWS API Gateway (HTTP APIs)", "Manages ingress, TLS termination, and mTLS verification for external payment gateways.")
    Component(Path_Segregation_Router, "Path Segregation Router", "AWS API Gateway Routing Rules", "Routes authorization scoring requests to the scoring engine and analyst requests to the case management container.")
    Component(Audit_Logging_Publisher, "Audit Logging Publisher", "AWS API Gateway Native Integration", "Streams compressed access logs to Amazon Kinesis Data Firehose for auditability.")
}

Rel(Ingress_and_TLS_Termination_Controller, Path_Segregation_Router, "Forwards authenticated and terminated HTTP requests")
Rel(Path_Segregation_Router, Audit_Logging_Publisher, "Triggers log emission for all processed traffic")

@enduml

Case Management Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(case_management_container, "Case Management Container") {
    Component(Case_Management_Frontend, "Case Management Frontend", "Static SPA on Amazon S3 and Amazon CloudFront", "Provides the user interface for fraud analysts and risk managers to manage cases and review alerts.")
    Component(Case_Management_Backend, "Case Management Backend", "Node.js API on Amazon ECS on Amazon Fargate", "Processes analyst requests, manages business logic, and coordinates data persistence and notifications.")
}

Rel(Case_Management_Frontend, Case_Management_Backend, "Invokes REST API", "HTTPS")

@enduml

Amazon RDS PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_rds_postgresql, "Amazon RDS PostgreSQL") {
    Component(Cases_DB_Schema, "Cases DB Schema", "PostgreSQL Database Schema", "Stores case management data and audit logs for fraud analyst review.")
    Component(Audit_Log_Schema, "Audit Log Schema", "PostgreSQL Database Schema with pgaudit & Trigger-Based RLS", "Maintains immutable audit records supporting PCI-DSS compliance.")
    Component(PgBouncer___RDS_Proxy, "PgBouncer / RDS Proxy", "AWS RDS Proxy / PgBouncer", "Provides connection pooling to handle high-concurrency connection spikes and prevent backend exhaustion.")
}

Rel(PgBouncer___RDS_Proxy, Cases_DB_Schema, "Routes and pools database connections for case management", "SQL / TLS 1.3")
Rel(PgBouncer___RDS_Proxy, Audit_Log_Schema, "Routes and pools database connections for audit logging", "SQL / TLS 1.3")

@enduml

Amazon S3 WORM Bucket & Model Bucket.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon S3 WORM Bucket & Model Bucket container

Container_Boundary(s3_container, "Amazon S3 WORM Bucket & Model Bucket") {
    Component(worm_storage, "WORM Object Storage", "Amazon S3 with WORM Object Lock & Versioning", "Provides secure, immutable storage meeting the 7-year audit requirement.")
    Component(model_bucket, "Model Bucket Storage", "Amazon S3", "Stores ONNX machine learning models retrieved by the Scoring Engine.")
}

System_Ext(scoring_engine, "Scoring Engine Container", "Go, ONNX runtime, Amazon ECS on AWS Fargate")
System_Ext(athena_datalake, "Amazon Athena & S3 Data Lake", "Analytics platform")

Rel(scoring_engine, model_bucket, "Loads ONNX models", "HTTPS (TLS 1.3), AWS IAM SigV4, VPC Gateway Endpoints")
Rel(athena_datalake, worm_storage, "Executes SQL queries for analytics", "SQL queries, HTTPS")

@enduml
